    def readints():
        return list(map(int, sys.stdin.readline().split()))

    n, m, k = readints()
    castles = [readints() for _ in range(n)]
    portals = [readints() for _ in range(m)]

    # Sort portals by destination castle
    portals.sort(key=lambda x: x[1])

    # Initialize DP table
    dp = [[-float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][k] = 0

    for i in range(1, n + 1):
        a, b, c = castles[i - 1]
        for j in range(k + 1):
            if dp[i - 1][j] == -float('inf'):
                continue
            # Option 1: Capture the castle
            if j >= a:
                dp[i][j - a] = max(dp[i][j - a], dp[i - 1][j] + c)
            # Option 2: Hire warriors
            if j + b <= k:
                dp[i][j + b] = max(dp[i][j + b], dp[i - 1][j])

    # Use portals to reinforce castles
    for i in range(1, n + 1):
        a, b, c = castles[i - 1]
        for j in range(k + 1):
            if dp[i][j] == -float('inf'):
                continue
            # Use portals to reinforce previous castles
            for u, v in portals:
                if u == i:
                    dp[v][j - 1] = max(dp[v][j - 1], dp[u][j])

    # Find the maximum score
    max_score = max(dp[n])
    if max_score == -float('inf'):
